def archive_logs(engine, before):
    with engine.begin() as conn:
        copied = conn.execute(
            insert(logs_archive).from_select(["id", "level", "message", "at"], select(logs.c.id, logs.c.level, logs.c.message, logs.c.at).where(logs.c.at < before))
        ).rowcount
        removed = conn.execute(delete(logs).where(logs.c.at < before)).rowcount
    if copied != removed:
        logger.warning("archived %d rows but removed %d", copied, removed)
    return copied, removed

def distinct_values(conn, table, column):
    allowed = {"events": ("city", "category"), "members": ("city", "plan")}
    if table not in allowed or column not in allowed[table]:
        raise ValueError("not allowed")
    query = sql.SQL("SELECT DISTINCT {col} FROM {tbl} ORDER BY 1").format(col=sql.Identifier(column), tbl=sql.Identifier(table))
    with conn.cursor() as cur:
        cur.execute(query)
        return [row[0] for row in cur.fetchall()]

