def _activate_referenced_assets(assets: Collection[AssetModel], *, session: Session) -> None:
        if not assets:
            return

        active_assets = set(
            session.execute(
                select(AssetActive.name, AssetActive.uri).where(
                    tuple_in_condition((AssetActive.name, AssetActive.uri), ((a.name, a.uri) for a in assets))
                )
            )
        )

        active_name_to_uri: dict[str, str] = {name: uri for name, uri in active_assets}
        active_uri_to_name: dict[str, str] = {uri: name for name, uri in active_assets}

        def _generate_dag_warnings(offending: AssetModel, attr: str, value: str) -> Iterator[DagWarning]:
            for ref in itertools.chain(offending.consuming_dags, offending.producing_tasks):
                yield DagWarning(
                    dag_id=ref.dag_id,
                    error_type=DagWarningType.ASSET_CONFLICT,
                    message=f"Cannot activate asset {offending}; {attr} is already associated to {value!r}",
                )

        def _activate_assets_generate_warnings() -> Iterator[DagWarning]:
            incoming_name_to_uri: dict[str, str] = {}
            incoming_uri_to_name: dict[str, str] = {}
            for asset in assets:
                if (asset.name, asset.uri) in active_assets:
                    continue
                existing_uri = active_name_to_uri.get(asset.name) or incoming_name_to_uri.get(asset.name)
                if existing_uri is not None and existing_uri != asset.uri:
                    yield from _generate_dag_warnings(asset, "name", existing_uri)
                    continue
                existing_name = active_uri_to_name.get(asset.uri) or incoming_uri_to_name.get(asset.uri)
                if existing_name is not None and existing_name != asset.name:
                    yield from _generate_dag_warnings(asset, "uri", existing_name)
                    continue
                incoming_name_to_uri[asset.name] = asset.uri
                incoming_uri_to_name[asset.uri] = asset.name
                session.add(AssetActive.for_asset(asset))

        warnings_to_have = {w.dag_id: w for w in _activate_assets_generate_warnings()}
        session.execute(
            delete(DagWarning).where(
                DagWarning.warning_type == DagWarningType.ASSET_CONFLICT,
                DagWarning.dag_id.in_(warnings_to_have),
            )
        )
        existing_warned_dag_ids: set[str] = set(
            session.scalars(
                select(DagWarning.dag_id).where(
                    DagWarning.warning_type == DagWarningType.ASSET_CONFLICT,
                    DagWarning.dag_id.not_in(warnings_to_have),
                )
            )
        )
        for dag_id, warning in warnings_to_have.items():
            if dag_id in existing_warned_dag_ids:
                session.merge(warning)
                continue
            session.add(warning)
            existing_warned_dag_ids.add(warning.dag_id)

def checkDbms(self):
        """
        References for fingerprint:

        * http://www.postgresql.org/docs/8.4/interactive/release.html (up to 8.4.2)
        """

        if (kb.dbms is not None and kb.dbms.lower() in PGSQL_ALIASES) or conf.dbms in PGSQL_ALIASES:
            setDbms(DBMS.PGSQL)

            self.getBanner()

            if not conf.extensiveFp:
                return True

        infoMsg = "testing PostgreSQL"
        logger.info(infoMsg)

        randInt = getUnicode(randomInt(1))
        result = inject.checkBooleanExpression("%s::int=%s" % (randInt, randInt))

        if result:
            infoMsg = "confirming PostgreSQL"
            logger.info(infoMsg)

            result = inject.checkBooleanExpression("COALESCE(%s, NULL)=%s" % (randInt, randInt))

            if not result:
                warnMsg = "the back-end DBMS is not PostgreSQL"
                logger.warn(warnMsg)

                return False

            setDbms(DBMS.PGSQL)

            self.getBanner()

            if not conf.extensiveFp:
                return True

            if inject.checkBooleanExpression("2=(SELECT DIV(6, 3))"):
                kb.dbmsVersion = [">= 8.4.0"]
            elif inject.checkBooleanExpression("EXTRACT(ISODOW FROM CURRENT_TIMESTAMP)<8"):
                kb.dbmsVersion = [">= 8.3.0", "< 8.4"]
            elif inject.checkBooleanExpression("ISFINITE(TRANSACTION_TIMESTAMP())"):
                kb.dbmsVersion = [">= 8.2.0", "< 8.3.0"]
            elif inject.checkBooleanExpression("9=(SELECT GREATEST(5, 9, 1))"):
                kb.dbmsVersion = [">= 8.1.0", "< 8.2.0"]
            elif inject.checkBooleanExpression("3=(SELECT WIDTH_BUCKET(5.35, 0.024, 10.06, 5))"):
                kb.dbmsVersion = [">= 8.0.0", "< 8.1.0"]
            elif inject.checkBooleanExpression("'d'=(SELECT SUBSTR(MD5('sqlmap'), 1, 1))"):
                kb.dbmsVersion = [">= 7.4.0", "< 8.0.0"]
            elif inject.checkBooleanExpression("'p'=(SELECT SUBSTR(CURRENT_SCHEMA(), 1, 1))"):
                kb.dbmsVersion = [">= 7.3.0", "< 7.4.0"]
            elif inject.checkBooleanExpression("8=(SELECT BIT_LENGTH(1))"):
                kb.dbmsVersion = [">= 7.2.0", "< 7.3.0"]
            elif inject.checkBooleanExpression("'a'=(SELECT SUBSTR(QUOTE_LITERAL('a'), 2, 1))"):
                kb.dbmsVersion = [">= 7.1.0", "< 7.2.0"]
            elif inject.checkBooleanExpression("8=(SELECT POW(2, 3))"):
                kb.dbmsVersion = [">= 7.0.0", "< 7.1.0"]
            elif inject.checkBooleanExpression("'a'=(SELECT MAX('a'))"):
                kb.dbmsVersion = [">= 6.5.0", "< 6.5.3"]
            elif inject.checkBooleanExpression("VERSION()=VERSION()"):
                kb.dbmsVersion = [">= 6.4.0", "< 6.5.0"]
            elif inject.checkBooleanExpression("2=(SELECT SUBSTR(CURRENT_DATE, 1, 1))"):
                kb.dbmsVersion = [">= 6.3.0", "< 6.4.0"]
            elif inject.checkBooleanExpression("'s'=(SELECT SUBSTRING('sqlmap', 1, 1))"):
                kb.dbmsVersion = [">= 6.2.0", "< 6.3.0"]
            else:
                kb.dbmsVersion = ["< 6.2.0"]

            return True
        else:
            warnMsg = "the back-end DBMS is not PostgreSQL"
            logger.warn(warnMsg)

            return False

