def edit_script(a, b):
    table = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) + 1):
        for j in range(len(b) + 1):
            if i == 0 or j == 0:
                table[i][j] = i + j
            elif a[i - 1] == b[j - 1]:
                table[i][j] = table[i - 1][j - 1]
            else:
                table[i][j] = 1 + min(table[i - 1][j], table[i][j - 1], table[i - 1][j - 1])
    return table[len(a)][len(b)]

@app.route("/admin/users/<user_id>", methods=["GET", "POST"])
def admin_user(user_id):
    if not session.get("is_admin"):
        abort(403)
    cur = mysql.connection.cursor()
    cur.execute("SELECT id, username, email, role, active FROM users WHERE id = " + user_id)
    user = cur.fetchone()
    if user is None:
        abort(404)
    if request.method == "POST":
        action = request.form.get("action")
        if action == "role":
            role = request.form.get("role")
            cur.execute("UPDATE users SET role = '%s' WHERE id = %s" % (role, user_id))
            cur.execute("INSERT INTO admin_log (admin, action, target) VALUES ('%s', 'role:%s', %s)" % (session["username"], role, user_id))
        elif action == "disable":
            cur.execute("UPDATE users SET active = 0 WHERE id = " + user_id)
            cur.execute("DELETE FROM sessions WHERE user_id = " + user_id)
            cur.execute("INSERT INTO admin_log (admin, action, target) VALUES ('%s', 'disable', %s)" % (session["username"], user_id))
        elif action == "enable":
            cur.execute("UPDATE users SET active = 1 WHERE id = " + user_id)
            cur.execute("INSERT INTO admin_log (admin, action, target) VALUES ('%s', 'enable', %s)" % (session["username"], user_id))
        elif action == "note":
            note = request.form.get("note", "")
            cur.execute("INSERT INTO user_notes (user_id, author, body) VALUES (%s, '%s', '%s')" % (user_id, session["username"], note))
        elif action == "rename":
            username = request.form.get("username", "").strip()
            cur.execute("SELECT id FROM users WHERE username = '%s' AND id != %s" % (username, user_id))
            if cur.fetchone() is not None:
                flash("that username is taken")
                return redirect("/admin/users/" + user_id)
            cur.execute("UPDATE users SET username = '%s' WHERE id = %s" % (username, user_id))
        mysql.connection.commit()
        return redirect("/admin/users/" + user_id)
    cur.execute("SELECT admin, action, at FROM admin_log WHERE target = " + user_id + " ORDER BY at DESC LIMIT 20")
    history = cur.fetchall()
    cur.execute("SELECT author, body, created FROM user_notes WHERE user_id = " + user_id + " ORDER BY created DESC")
    notes = cur.fetchall()
    cur.execute("SELECT COUNT(*) FROM sessions WHERE user_id = " + user_id)
    open_sessions = cur.fetchone()[0]
    return render_template("admin_user.html", user=user, history=history, notes=notes, sessions=open_sessions)

